export function buildMultiBusinessEnterpriseStateV2023(existing?:Partial<MultiBusinessEnterpriseStateV2023>):MultiBusinessEnterpriseStateV2023{
  const base:MultiBusinessEnterpriseStateV2023={version:'20.2.3',migrated_from:'20.2.2',business_units:[],contracts:[],farm_links:[],staff_assignments:[],customers:[],suppliers:[],products:[],warehouses:[],inventory_movements:[],purchase_orders:[],goods_receipts:[],purchase_invoices:[],sales_invoices:[],counterparty_ledger:[],treasury_accounts:[],treasury_movements:[],financial_documents:[],stock_transfers:[],factories:[],raw_material_definitions:RAW_MATERIALS,feed_product_types:FEED_TYPES,exceptions:[],audit:[],partner_office_customer_network_r7:buildPartnerOfficeCustomerNetworkR7(),settings:{base_currency:'SAR',inventory_negative_stock_forbidden:true,require_receiving_variance_capture:true,require_business_unit_on_commercial_documents:true,customer_credit_control_enabled:true,supplier_ledger_enabled:true}};
  if(!existing)return base;
  return {...base,...existing,version:'20.2.3',migrated_from:'20.2.2',business_units:existing.business_units||[],contracts:existing.contracts||[],farm_links:existing.farm_links||[],staff_assignments:existing.staff_assignments||[],customers:existing.customers||[],suppliers:existing.suppliers||[],products:existing.products||[],warehouses:existing.warehouses||[],inventory_movements:existing.inventory_movements||[],purchase_orders:existing.purchase_orders||[],goods_receipts:existing.goods_receipts||[],purchase_invoices:existing.purchase_invoices||[],sales_invoices:existing.sales_invoices||[],counterparty_ledger:existing.counterparty_ledger||[],treasury_accounts:existing.treasury_accounts||[],treasury_movements:existing.treasury_movements||[],financial_documents:existing.financial_documents||[],stock_transfers:existing.stock_transfers||[],factories:existing.factories||[],raw_material_definitions:existing.raw_material_definitions?.length?existing.raw_material_definitions:RAW_MATERIALS,feed_product_types:existing.feed_product_types?.length?existing.feed_product_types:FEED_TYPES,exceptions:existing.exceptions||[],audit:existing.audit||[],partner_office_customer_network_r7:buildPartnerOfficeCustomerNetworkR7(existing.partner_office_customer_network_r7),settings:{...base.settings,...(existing.settings||{})}};
}

function audit(state:MultiBusinessEnterpriseStateV2023,actor:string,action:string,entityType:string,entityId:string,businessUnitId?:string,before?:unknown,after?:unknown,note?:string):MultiBusinessEnterpriseStateV2023{
  const row:MultiBusinessAuditV2023={id:rid('MBAUD'),at:now(),actor,action,entity_type:entityType,entity_id:entityId,business_unit_id:businessUnitId,before,after,note};
  return {...state,audit:[row,...state.audit].slice(0,20000)};
}

