export function ensureMultiBusinessFinanceV2023(web:EnterpriseWebStateV202,state:MultiBusinessEnterpriseStateV2023):EnterpriseWebStateV202{
  let next={...web,chart_of_accounts:[...web.chart_of_accounts]};
  for(const account of EXTRA_ACCOUNTS)if(!next.chart_of_accounts.some(a=>a.code===account.code))next.chart_of_accounts.push(account);
  for(const unit of state.business_units){
    const code=unit.cost_center_code;
    if(!next.cost_centers.some(c=>c.code===code)){
      const row:CostCenterV202={id:rid('CCBU'),code,name:`${unit.name} / Operations`,category:'business_unit',active:true};
      next={...next,cost_centers:[row,...next.cost_centers]};
    }
  }
  return next;
}

function unitCostCenterId(web:EnterpriseWebStateV202,unit:BusinessUnitV2023){return web.cost_centers.find(c=>c.code===unit.cost_center_code)?.id;}
function requireUnit(state:MultiBusinessEnterpriseStateV2023,id:string){const x=state.business_units.find(v=>v.id===id);if(!x)throw new Error('business_unit_not_found');return x;}
function requireWarehouse(state:MultiBusinessEnterpriseStateV2023,id:string){const x=state.warehouses.find(v=>v.id===id);if(!x)throw new Error('warehouse_not_found');return x;}
function requireProduct(state:MultiBusinessEnterpriseStateV2023,id:string){const x=state.products.find(v=>v.id===id);if(!x)throw new Error('product_not_found');return x;}
function requireCustomer(state:MultiBusinessEnterpriseStateV2023,id:string){const x=state.customers.find(v=>v.id===id);if(!x)throw new Error('customer_not_found');return x;}
function requireSupplier(state:MultiBusinessEnterpriseStateV2023,id:string){const x=state.suppliers.find(v=>v.id===id);if(!x)throw new Error('supplier_not_found');return x;}

export function createBusinessUnitV2023(state:MultiBusinessEnterpriseStateV2023,input:Omit<BusinessUnitV2023,'id'|'cost_center_code'|'created_at'>,actor:string):MultiBusinessEnterpriseStateV2023{
  const code=input.code.trim().toUpperCase();if(!code||state.business_units.some(x=>x.code===code))throw new Error('business_unit_code_required_or_duplicate');
  if(input.parent_business_unit_id&&!state.business_units.some(x=>x.id===input.parent_business_unit_id))throw new Error('parent_business_unit_not_found');
  const row:BusinessUnitV2023={...input,code,id:rid('BU'),cost_center_code:`BU:${code}:OPS`,created_at:now()};
  return audit({...state,business_units:[row,...state.business_units]},actor,'business_unit_create','business_unit',row.id,row.id,undefined,row);
}

export function createBusinessContractV2023(state:MultiBusinessEnterpriseStateV2023,input:Omit<BusinessContractV2023,'id'|'contract_number'|'created_at'>,actor:string):MultiBusinessEnterpriseStateV2023{
  requireUnit(state,input.business_unit_id);
  if(!Number.isFinite(input.platform_commission_percent)||input.platform_commission_percent<0||input.platform_commission_percent>100)throw new Error('invalid_platform_commission');
  // Contract acceptance and its farm assignments are one atomic state transition.
  // Draft/expired/terminated contracts must not expose a farm to an office.
  const farmIds=(input.linked_farm_ids||[]).map(x=>String(x).trim());
  if(farmIds.some(x=>!x)||new Set(farmIds).size!==farmIds.length)throw new Error('invalid_or_duplicate_contract_farm');
  if(input.status==='active')for(const farmId of farmIds){
    if(state.farm_links.some(x=>x.farm_id===farmId&&x.active))throw new Error('farm_already_linked_to_active_business_unit');
  }
  const row:BusinessContractV2023={...input,linked_farm_ids:farmIds,id:rid('BCTR'),contract_number:serial('BCTR'),created_at:now()};
  const links:BusinessFarmLinkV2023[]=row.status==='active'?farmIds.map(farmId=>({
    id:rid('BUFRM'),business_unit_id:row.business_unit_id,farm_id:farmId,contract_id:row.id,
    cost_center_code:`BU:${row.business_unit_id}:FARM:${farmId}`,active:true,starts_at:row.start_date
  })):[];
  let next={...state,contracts:[row,...state.contracts],farm_links:[...links,...state.farm_links],business_units:state.business_units.map(u=>u.id===row.business_unit_id?{...u,contract_id:row.id}:u)};
  next=audit(next,actor,'business_contract_create','business_contract',row.id,row.business_unit_id,undefined,row);
  for(const link of links)next=audit(next,actor,'farm_business_link_create','farm_business_link',link.id,row.business_unit_id,undefined,link,'created_with_active_contract');
  return next;
}

export function linkFarmToBusinessUnitV2023(state:MultiBusinessEnterpriseStateV2023,input:Omit<BusinessFarmLinkV2023,'id'>,actor:string):MultiBusinessEnterpriseStateV2023{
  requireUnit(state,input.business_unit_id);
  if(!input.farm_id?.trim())throw new Error('farm_id_required');
  if(input.contract_id){
    const contract=state.contracts.find(c=>c.id===input.contract_id);
    if(!contract||contract.business_unit_id!==input.business_unit_id||contract.status!=='active'||!contract.linked_farm_ids.includes(input.farm_id))throw new Error('farm_contract_scope_invalid');
  }
  if(input.active&&state.farm_links.some(x=>x.farm_id===input.farm_id&&x.active))throw new Error('farm_already_linked_to_active_business_unit');
  const row:BusinessFarmLinkV2023={...input,id:rid('BUFRM')};return audit({...state,farm_links:[row,...state.farm_links]},actor,'farm_business_link_create','farm_business_link',row.id,row.business_unit_id,undefined,row);
}

