  const inv:SalesInvoiceV2023={id:rid('SINV'),invoice_number:serial('SINV'),business_unit_id:unit.id,warehouse_id:warehouse.id,customer_id:customer.id,invoice_date:input.invoice_date,invoice_time:input.invoice_time,payment_term:input.payment_term,currency:input.currency,original_amount:original,exchange_rate_to_sar:input.exchange_rate_to_sar,total_sar:total,paid_sar:input.payment_term==='cash'?total:0,balance_sar:input.payment_term==='cash'?0:total,due_date:input.payment_term==='credit'?addDays(input.invoice_date,customer.credit_days):input.invoice_date,lines:invoiceLines,status:input.payment_term==='cash'?'paid':'open',journal_entry_ids:[],issued_by:input.issued_by,recipient_name:input.recipient_name,created_at:now()};next={...next,inventory_movements:next.inventory_movements.map(m=>m.source_type==='sales_invoice'&&m.source_id==='pending'?{...m,source_id:inv.id}:m)};
