export function customerBalanceV2023(state:MultiBusinessEnterpriseStateV2023,customerId:string){return round(state.counterparty_ledger.filter(x=>x.party_type==='customer'&&x.party_id===customerId).reduce((s,x)=>s+x.debit_sar-x.credit_sar,0));}
export function supplierBalanceV2023(state:MultiBusinessEnterpriseStateV2023,supplierId:string){return round(state.counterparty_ledger.filter(x=>x.party_type==='supplier'&&x.party_id===supplierId).reduce((s,x)=>s+x.credit_sar-x.debit_sar,0));}
export function treasuryBalanceV2023(state:MultiBusinessEnterpriseStateV2023,accountId:string){const a=state.treasury_accounts.find(x=>x.id===accountId);if(!a)return 0;return round(a.opening_balance+state.treasury_movements.filter(x=>x.treasury_account_id===accountId).reduce((s,x)=>s+(x.direction==='in'?x.original_amount:-x.original_amount),0));}

export function businessUnitFinancialSummaryV2023(state:MultiBusinessEnterpriseStateV2023,web:EnterpriseWebStateV202,businessUnitId:string){
  const unit=requireUnit(state,businessUnitId),nextWeb=ensureMultiBusinessFinanceV2023(web,state),cc=unitCostCenterId(nextWeb,unit);const posted=nextWeb.journal_entries.filter(j=>j.status==='posted');const lines=posted.flatMap(j=>j.lines.filter(l=>!cc||l.cost_center_id===cc));const accountType=(code:string)=>nextWeb.chart_of_accounts.find(a=>a.code===code)?.type;const revenue=round(lines.filter(l=>accountType(l.account_code)==='revenue').reduce((s,l)=>s+l.credit_sar-l.debit_sar,0));const expense=round(lines.filter(l=>accountType(l.account_code)==='expense').reduce((s,l)=>s+l.debit_sar-l.credit_sar,0));const assets=round(lines.filter(l=>accountType(l.account_code)==='asset').reduce((s,l)=>s+l.debit_sar-l.credit_sar,0));const liabilities=round(lines.filter(l=>accountType(l.account_code)==='liability').reduce((s,l)=>s+l.credit_sar-l.debit_sar,0));return {business_unit:unit,revenue_sar:revenue,expense_sar:expense,profit_loss_sar:round(revenue-expense),assets_movement_sar:assets,liabilities_movement_sar:liabilities,journal_count:posted.filter(j=>j.lines.some(l=>!cc||l.cost_center_id===cc)).length};
}

export function businessUnitDashboardV2023(state:MultiBusinessEnterpriseStateV2023,businessUnitId:string,veterinary?:VeterinaryFieldStateV2022){
  const unit=requireUnit(state,businessUnitId),warehouseIds=new Set(state.warehouses.filter(w=>w.business_unit_id===unit.id).map(w=>w.id));const customerIds=new Set(state.customers.filter(c=>c.business_unit_id===unit.id).map(c=>c.id));const supplierIds=new Set(state.suppliers.filter(s=>s.business_unit_id===unit.id).map(s=>s.id));const sales=state.sales_invoices.filter(x=>x.business_unit_id===unit.id),purchases=state.purchase_invoices.filter(x=>x.business_unit_id===unit.id);const farmIds=new Set(state.farm_links.filter(x=>x.business_unit_id===unit.id&&x.active).map(x=>x.farm_id));const stockRows=state.products.map(p=>({product:p,quantity:[...warehouseIds].reduce((s,w)=>s+inventoryBalanceV2023(state,w,p.id),0)})).filter(x=>x.quantity!==0);const lowStock=stockRows.filter(x=>x.quantity<=x.product.minimum_stock_base);const cases=veterinary?veterinary.medical_cases.filter(c=>farmIds.has(c.farm_id)&&c.status!=='closed'):[];
  return {business_unit:unit,farm_count:farmIds.size,customer_count:customerIds.size,supplier_count:supplierIds.size,warehouse_count:warehouseIds.size,sales_sar:round(sales.reduce((s,x)=>s+x.total_sar,0)),receivables_sar:round(sales.reduce((s,x)=>s+x.balance_sar,0)),purchases_sar:round(purchases.reduce((s,x)=>s+x.total_sar,0)),payables_sar:round(purchases.reduce((s,x)=>s+x.balance_sar,0)),inventory_value_sar:round(stockRows.reduce((s,x)=>s+x.quantity*x.product.purchase_price,0)),low_stock_count:lowStock.length,open_exceptions:state.exceptions.filter(x=>x.business_unit_id===unit.id&&x.status!=='resolved').length,open_medical_cases:cases.length,critical_medical_cases:cases.filter(c=>c.severity==='critical').length,treasury_accounts:state.treasury_accounts.filter(x=>x.business_unit_id===unit.id).map(x=>({...x,current_balance:treasuryBalanceV2023(state,x.id)}))};
}
export function platformBusinessDashboardV2023(state:MultiBusinessEnterpriseStateV2023,veterinary?:VeterinaryFieldStateV2022){const active=state.business_units.filter(x=>x.status==='active');const rows=active.map(x=>businessUnitDashboardV2023(state,x.id,veterinary));return {active_business_units:active.length,offices:active.filter(x=>['office','medicine_office','feed_office','equipment_office','chick_office'].includes(x.type)).length,factories:active.filter(x=>x.type==='feed_factory').length,farms:new Set(state.farm_links.filter(x=>x.active).map(x=>x.farm_id)).size,customers:state.customers.filter(x=>x.active).length,suppliers:state.suppliers.filter(x=>x.active).length,sales_sar:round(rows.reduce((s,x)=>s+x.sales_sar,0)),receivables_sar:round(rows.reduce((s,x)=>s+x.receivables_sar,0)),purchases_sar:round(rows.reduce((s,x)=>s+x.purchases_sar,0)),payables_sar:round(rows.reduce((s,x)=>s+x.payables_sar,0)),inventory_value_sar:round(rows.reduce((s,x)=>s+x.inventory_value_sar,0)),open_exceptions:state.exceptions.filter(x=>x.status!=='resolved').length,critical_medical_cases:rows.reduce((s,x)=>s+x.critical_medical_cases,0),units:rows};}
export function factoryDashboardV2023(state:MultiBusinessEnterpriseStateV2023,factoryId:string){const f=state.factories.find(x=>x.id===factoryId);if(!f)throw new Error('factory_not_found');const rawWarehouse=f.raw_material_warehouse_id;const rows=rawWarehouse?state.products.filter(p=>p.category==='raw_material').map(p=>({product_id:p.id,sku:p.sku,name:p.name,...inventoryDisplayV2023(inventoryBalanceV2023(state,rawWarehouse,p.id),p)})):[];return {factory:f,raw_materials:rows,raw_material_count:rows.length,raw_material_kg:round(rows.reduce((s,r)=>s+(r.kg||0),0),3),raw_material_tons:round(rows.reduce((s,r)=>s+(r.tons||0),0),3),feed_types:state.feed_product_types,raw_material_definitions:state.raw_material_definitions};}

export function customerStatementV2023(state:MultiBusinessEnterpriseStateV2023,customerId:string){const customer=requireCustomer(state,customerId);const entries=state.counterparty_ledger.filter(x=>x.party_type==='customer'&&x.party_id===customer.id).sort((a,b)=>a.occurred_at.localeCompare(b.occurred_at));let balance=0;return {customer,entries:entries.map(x=>{balance=round(balance+x.debit_sar-x.credit_sar);return {...x,running_balance_sar:balance}}),balance_sar:balance};}
