export function validateMultiBusinessStateV2023(state:MultiBusinessEnterpriseStateV2023,web?:EnterpriseWebStateV202):string[]{
  const issues:string[]=[];const uniq=(rows:string[],label:string)=>{const s=new Set<string>();for(const x of rows){if(s.has(x))issues.push(`${label}_duplicate:${x}`);s.add(x)}};uniq(state.business_units.map(x=>x.code),'business_unit_code');uniq(state.products.map(x=>x.sku),'product_sku');uniq(state.warehouses.map(x=>x.code),'warehouse_code');uniq(state.financial_documents.map(x=>x.document_number),'financial_document_number');
  const unitIds=new Set(state.business_units.map(x=>x.id)),warehouseIds=new Set(state.warehouses.map(x=>x.id)),productIds=new Set(state.products.map(x=>x.id)),customerIds=new Set(state.customers.map(x=>x.id)),supplierIds=new Set(state.suppliers.map(x=>x.id));for(const w of state.warehouses)if(!unitIds.has(w.business_unit_id))issues.push(`warehouse_orphan_unit:${w.id}`);for(const c of state.customers)if(!unitIds.has(c.business_unit_id))issues.push(`customer_orphan_unit:${c.id}`);for(const s of state.suppliers)if(!unitIds.has(s.business_unit_id))issues.push(`supplier_orphan_unit:${s.id}`);for(const m of state.inventory_movements){if(!warehouseIds.has(m.warehouse_id))issues.push(`movement_orphan_warehouse:${m.id}`);if(!productIds.has(m.product_id))issues.push(`movement_orphan_product:${m.id}`);if(m.quantity_base<0)issues.push(`movement_negative_quantity:${m.id}`);}for(const inv of state.sales_invoices){if(!customerIds.has(inv.customer_id))issues.push(`sales_invoice_orphan_customer:${inv.id}`);const sum=round(inv.lines.reduce((s,l)=>s+l.line_total_sar,0));if(Math.abs(sum-inv.total_sar)>0.01)issues.push(`sales_invoice_total_mismatch:${inv.id}`);if(inv.balance_sar<0)issues.push(`sales_invoice_negative_balance:${inv.id}`);}for(const inv of state.purchase_invoices){if(!supplierIds.has(inv.supplier_id))issues.push(`purchase_invoice_orphan_supplier:${inv.id}`);if(inv.balance_sar<0)issues.push(`purchase_invoice_negative_balance:${inv.id}`);}for(const w of state.warehouses)for(const p of state.products){const b=inventoryBalanceV2023(state,w.id,p.id);if(state.settings.inventory_negative_stock_forbidden&&b<-0.0001)issues.push(`negative_stock:${w.id}:${p.id}:${b}`);}for(const tr of state.stock_transfers)if(tr.status==='received'&&!tr.received_at)issues.push(`received_transfer_missing_timestamp:${tr.id}`);if(web){for(const u of state.business_units.filter(x=>x.status==='active'))if(!web.cost_centers.some(c=>c.code===u.cost_center_code))issues.push(`business_unit_cost_center_missing:${u.id}`);for(const code of EXTRA_ACCOUNTS.map(a=>a.code))if(!web.chart_of_accounts.some(a=>a.code===code))issues.push(`financial_account_missing:${code}`);}return issues;
}
